#!/usr/bin/env python3
import hashlib, html, json, runpy, time
from pathlib import Path
base=runpy.run_path(str(Path(__file__).with_name('publish_recipe_20260830_1000.py')),run_name='recipe_base')
TITLE='Feijão Amassado com Abóbora para Bebê: Receita Cremosa e Simples'; SLUG_KEY='feijao-amassado-abobora-bebe'; CLUSTER='Cluster 5 — Refeições com feijão, lentilha, grão-de-bico e outras leguminosas'; KEYWORD='feijão amassado com abóbora para bebê'
MARKER=base['MARKER']; BLOG_ID=base['BLOG_ID']; COVER_DIR=base['COVER_DIR']; RAW_BASE=base['RAW_BASE']; LOG_PATH=base['LOG_PATH']; RESULT_PATH=base['RESULT_PATH']
def article(cover):
 schema={'@context':'https://schema.org','@type':'Recipe','name':TITLE,'image':[cover],'author':{'@type':'Organization','name':'Equipe Editorial do Receitas Para Pequenos'},'description':'Feijão amassado com abóbora cozida, uma preparação de colher simples e com textura ajustável para alimentação complementar.','recipeCategory':'Almoço e jantar','recipeCuisine':'Brasileira','keywords':KEYWORD+', alimentação complementar, feijão, abóbora, leguminosas','recipeYield':'2 porções pequenas','recipeIngredient':['1/2 xícara de feijão cozido com alguns grãos e caldo','1/2 xícara de abóbora cozida em cubos','1 colher (sopa) de cebola bem picada','água do cozimento, somente se necessário para ajustar a consistência'],'recipeInstructions':[{'@type':'HowToStep','text':'Cozinhe a abóbora até ficar bem macia.'},{'@type':'HowToStep','text':'Amasse a abóbora com um garfo e junte o feijão cozido.'},{'@type':'HowToStep','text':'Amasse os grãos de feijão junto da abóbora, mantendo a consistência espessa e ajustando com um pouco do líquido do cozimento somente se necessário.'},{'@type':'HowToStep','text':'Espere amornar e adapte a textura às habilidades da criança antes de servir.'}]}
 sj=json.dumps(schema,ensure_ascii=False).replace('</','<\\/'); alt=html.escape(TITLE,quote=True)
 return f"""{MARKER}<div class='separator' style='clear:both;margin:0 0 24px;text-align:center'><img alt='{alt}' data-original-height='630' data-original-width='1200' src='{cover}' style='border-radius:14px;height:auto;max-width:100%;width:1200px'/></div><p><strong>Por Equipe Editorial do Receitas Para Pequenos</strong></p><p>Feijão amassado com abóbora é uma forma simples de combinar uma leguminosa comum na mesa brasileira com um legume macio. Nesta versão, os grãos são amassados com o garfo e a preparação fica espessa, sem precisar bater no liquidificador.</p><p><strong>Atenção:</strong> adapte a consistência e a forma de servir às habilidades da criança e ofereça a refeição sempre com ela sentada e supervisionada. Alergias, dificuldades de mastigação ou deglutição e necessidades especiais devem ser avaliadas por profissional habilitado.</p><h2>Ingredientes</h2><ul><li>1/2 xícara de feijão cozido, com alguns grãos e caldo</li><li>1/2 xícara de abóbora cozida em cubos</li><li>1 colher (sopa) de cebola bem picada</li><li>Um pouco da água do cozimento, somente se for necessário ajustar a consistência</li></ul><h2>Modo de preparo</h2><ol><li>Cozinhe a abóbora até ficar bem macia e fácil de esmagar com o garfo.</li><li>Se estiver preparando a cebola junto da refeição, cozinhe-a até ficar macia.</li><li>Amasse a abóbora com um garfo.</li><li>Acrescente o feijão cozido e amasse os grãos junto da abóbora. Não é necessário transformar tudo em creme liso.</li><li>Misture até obter uma preparação úmida e espessa. Se estiver seca demais, use uma pequena quantidade do próprio líquido do cozimento para ajustar.</li><li>Espere amornar antes de servir.</li></ol><h2>Como deve ficar a textura</h2><p>A mistura deve ficar macia, úmida e espessa o suficiente para permanecer na colher. Os grãos podem ser amassados com o garfo, preservando gradualmente mais textura conforme as habilidades da criança evoluem. O objetivo não é deixar a refeição líquida nem depender do liquidificador.</p><h2>Como servir e adaptar</h2><p>Sirva em pequena quantidade e ajuste a textura às habilidades da criança. O Ministério da Saúde orienta que, no início da alimentação complementar, os alimentos sejam oferecidos amassados com garfo e que a consistência evolua gradualmente, em vez de manter preparações liquidificadas ou peneiradas.</p><h2>Por que usar feijão e abóbora juntos?</h2><p>A combinação funciona culinariamente porque a abóbora cozida amassa com facilidade e ajuda a formar uma preparação cremosa, enquanto o feijão mantém o sabor e a textura característicos da leguminosa. O Guia Alimentar para Crianças Brasileiras Menores de 2 Anos inclui feijões, lentilha, ervilha e grão-de-bico no grupo das leguminosas.</p><h2>Substituições culinárias</h2><p>A abóbora pode ser trocada por batata-doce ou mandioca bem cozida, lembrando que cada ingrediente altera a quantidade de líquido necessária. Outros tipos de feijão também podem mudar sabor e consistência. Em caso de alergias ou necessidades alimentares específicas, a adaptação deve ser orientada por profissional habilitado.</p><h2>Armazenamento</h2><p>Por envolver alimento cozido destinado a criança pequena, prepare com mãos, utensílios e superfícies limpos e evite guardar novamente a porção que já teve contato com a boca ou com o utensílio usado durante a refeição. Para conservar sobras, siga as orientações oficiais de higiene, refrigeração e reaquecimento aplicáveis à sua rotina, sem deixar a preparação por longos períodos em temperatura ambiente.</p><h2>Perguntas frequentes</h2><h3>Precisa bater o feijão no liquidificador?</h3><p>Não. Nesta receita, os grãos cozidos são amassados com garfo junto da abóbora. A textura pode ser ajustada progressivamente conforme as habilidades da criança.</p><h3>Posso deixar mais ralo?</h3><p>Se a mistura estiver seca, acrescente pouco líquido do cozimento por vez. A ideia é manter uma consistência espessa, e não transformar a preparação em caldo.</p><h3>Posso usar outro tipo de abóbora?</h3><p>Sim. Use uma variedade que cozinhe até ficar macia; a quantidade de líquido pode mudar conforme a umidade da abóbora escolhida.</p><h2>Receitas relacionadas</h2><ul><li><a href='https://www.receitasparapequenos.site/2026/08/bolinho-de-lentilha-assado-para-bebe.html'>Bolinho de Lentilha Assado para Bebê</a></li><li><a href='https://www.receitasparapequenos.site/2026/08/hamburguer-de-grao-de-bico-macio-para.html'>Hambúrguer de Grão-de-Bico Macio para Bebê</a></li><li><a href='https://www.receitasparapequenos.site/2026/08/creme-de-lentilha-com-legumes-para-bebe.html'>Creme de Lentilha com Legumes para Bebê</a></li></ul><h2>Referências oficiais</h2><ul><li><a href='https://www.gov.br/saude/pt-br/assuntos/saude-de-a-a-z/s/saude-da-crianca/primeira-infancia/alimentacao-saudavel' rel='nofollow'>Ministério da Saúde — Alimentação saudável na primeira infância</a></li><li><a href='https://www.gov.br/saude/pt-br/assuntos/saude-brasil/eu-quero-me-alimentar-melhor/Documentos/pdf/guia-alimentar-para-criancas-brasileiras-menores-de-2-anos.pdf/' rel='nofollow'>Ministério da Saúde — Guia Alimentar para Crianças Brasileiras Menores de 2 Anos</a></li></ul><h2>Conclusão</h2><p>O feijão amassado com abóbora é uma preparação de colher simples, diferente dos bolinhos e hambúrgueres do mesmo cluster. O ponto principal é cozinhar bem os ingredientes, manter uma textura espessa e adaptar a consistência às habilidades da criança.</p><script type='application/ld+json'>{sj}</script>"""
def main():
 tok=base['token'](); posts=base['list_posts'](tok)
 for p in posts:
  t=(p.get('title') or '').casefold()
  if t==TITLE.casefold() or ('feijão' in t and 'abóbora' in t) or ('feijao' in t and 'abobora' in t):
   RESULT_PATH.write_text(f'outcome=skipped_duplicate\ntitle={p.get("title","")}\nurl={p.get("url","")}\n',encoding='utf-8'); base['git_commit_push']([RESULT_PATH],'Record duplicate prevention for bean pumpkin recipe'); return
 suffix=hashlib.sha1(TITLE.encode()).hexdigest()[:10]; cp=COVER_DIR/f'{SLUG_KEY}-{suffix}.jpg'; cu=f'{RAW_BASE}/{cp.name}'
 if not cp.exists():
  original=base['TITLE']; base['TITLE']=TITLE
  try: base['generate_cover'](cp)
  finally: base['TITLE']=original
  base['git_commit_push']([cp],'Add unique AI food photo for bean pumpkin recipe'); time.sleep(8)
 content=article(cu)
 if MARKER not in content or cu not in content: raise RuntimeError('cover verification failed before publish')
 created=base['api'](tok,'POST',f'/blogs/{BLOG_ID}/posts',{'isDraft':'false','fetchBody':'true'},{'kind':'blogger#post','blog':{'id':BLOG_ID},'title':TITLE,'content':content,'labels':['Alimentação complementar','Almoço','Jantar','Feijão','Leguminosas']}); pid=str(created.get('id','')); url=created.get('url','')
 if not pid: raise RuntimeError('Blogger did not return post id')
 vc=(base['api'](tok,'GET',f'/blogs/{BLOG_ID}/posts/{pid}',{'view':'ADMIN'}).get('content') or '')
 if MARKER not in vc or cu not in vc: raise RuntimeError('live Blogger post failed cover verification')
 log=base['load_log'](); log.append({'published_at':created.get('published'),'title':TITLE,'url':url,'post_id':pid,'cluster':CLUSTER,'keyword':KEYWORD,'cover_url':cu,'marker':MARKER}); LOG_PATH.write_text(json.dumps(log,ensure_ascii=False,indent=2)+'\n',encoding='utf-8'); RESULT_PATH.write_text('outcome=success\n'+f'title={TITLE}\nurl={url}\npost_id={pid}\ncluster={CLUSTER}\ncover_url={cu}\nmarker_verified=true\n',encoding='utf-8'); base['git_commit_push']([LOG_PATH,RESULT_PATH],'Record published bean pumpkin recipe')
if __name__=='__main__': main()
